   482          for (mg = 0; mg < params->HGH; ++mg) {
   483              for (ng = 0; ng < params->HGW; ++ng) {
   484                  x = (params->HGX + mg * params->HRY + ng * params->HRX) >> 8;
   485                  y = (params->HGY + mg * params->HRX - ng * params->HRY) >> 8;
