   487                  if (x + HPATS->HPW <= 0 || x >= (int32_t) image->width || y + HPATS->HPH <= 0 || y >= (int32_t) image->height) {
   488                      jbig2_image_set_pixel(HSKIP, ng, mg, 1);
   489                  } else {
   490                      jbig2_image_set_pixel(HSKIP, ng, mg, 0);
   491                  }
   492              }
   493          }
   494      }
