   509          code = jbig2_error(ctx, JBIG2_SEVERITY_WARNING, segment->number, "unable to acquire gray-scale image, skipping halftone image");
   510          goto cleanup;
   511      }
   512
   513      /* 6.6.5 point 5. place patterns with procedure mentioned in 6.6.5.2 */
