   248  /* dispatch code for profile segment parsing */
   249  static int
   250  jbig2_parse_profile_segment(Jbig2Ctx *ctx, Jbig2Segment *segment, const uint8_t *segment_data)
   251  {
   252      uint32_t profiles;
   253      uint32_t i;
